(async()=>{
const $=id=>document.getElementById(id), sections=['home','setup','play','result','stats','awards','profile','shop','createProfile'];let bank=[];
try{const r=await fetch('questions.json');if(!r.ok)throw Error('HTTP '+r.status);const j=await r.json();bank=j.questions.map(q=>({...q,options:[...q.options]}));}catch(e){$('bankNotice').textContent='Erreur de chargement des questions : '+e.message;return;}
const themes=[...new Set(bank.map(q=>q.theme))];const empty=()=>({xp:0,coins:0,games:0,streak:0,perfect:0,theme:{},seen:[],records:{},survivalTop:[],history:[],profile:null});let data=empty();try{const v=JSON.parse(localStorage.getItem('culture-arena-web-v1'));if(v)data={...empty(),...v}}catch(e){}
let mode='Classique',session=null,frame=0,penaltyTimeout=0,selectedTheme='Tous',selectedCount=10;
const gradeNames=['Novice','Apprenti','Curieux','Explorateur','Connaisseur','Érudit','Savant','Philosophe','Penseur','Maître du savoir','Grand érudit','Sage','Visionnaire','Génie','Prodige','Titan du savoir','Oracle','Immortel','Mythe vivant','Légende absolue'];
const gradeThresholds=[0,2000,6000,12000,20000,35000,55000,80000,110000,150000,200000,270000,360000,480000,650000,850000,1100000,1450000,1900000,2500000];
const grades=gradeNames.map((name,i)=>({level:i+1,name,xp:gradeThresholds[i],id:'grade-'+(i+1),image:'assets/grade-'+String(i+1).padStart(2,'0')+'.webp'}));
const avatarItems=[...grades.map(g=>({id:g.id,name:g.name,image:g.image,price:0,level:g.level})),
{id:'dragon',name:'Dragon ancien',image:'data:image/webp;base64,',price:50},{id:'phoenix',name:'Phénix',image:'data:image/webp;base64,',price:50},{id:'wizard',name:'Archimage',image:'data:image/webp;base64,',price:50},{id:'owl',name:'Gardien du savoir',image:'data:image/webp;base64,',price:50},{id:'crown',name:'Souverain',image:'data:image/webp;base64,',price:50},{id:'galaxy',name:'Oracle cosmique',image:'data:image/webp;base64,',price:50}];
const banners=[{id:'classic',name:'Classique',price:0},{id:'flame',name:'Flamme',price:200},{id:'ice',name:'Glace',price:200},{id:'forest',name:'Forêt',price:200},{id:'knowledge',name:'Savoir',price:300},{id:'celestial',name:'Céleste',price:300},{id:'royal',name:'Royale',price:400},{id:'obsidian',name:'Obsidienne',price:400},{id:'legendary',name:'Légendaire',price:500}];
function currentGrade(){return [...grades].reverse().find(g=>data.xp>=g.xp)||grades[0]}
function nextGrade(){return grades[currentGrade().level]||null}
function number(n){return Number(n||0).toLocaleString('fr-FR')}
function art(avatar,cls='avatar-art'){const img=document.createElement('img');img.className=cls;img.src=avatar.image;img.alt=avatar.name;img.loading='lazy';return img}
function bannerNode(name,bannerId){const el=document.createElement('div');el.className='banner '+(banners.some(b=>b.id===bannerId)?bannerId:'classic');el.textContent=name;return el}
function syncGradeUnlocks(){if(!data.profile)return;ensureProfile();for(const g of grades){if(data.xp>=g.xp&&!data.profile.owned.includes(g.id))data.profile.owned.push(g.id)}}
function getProfile(){return data.profile||null}
function validName(value){const name=value.trim();return name.length>=3&&name.length<=18&&!/[<>\u0000-\u001f]/.test(name)?name:null}
function ensureProfile(){if(!data.profile||typeof data.profile!=='object')data.profile={nickname:'',avatar:'grade-1',owned:['grade-1'],renameTokens:0,banner:'classic',ownedBanners:['classic']};const p=data.profile;if(!Array.isArray(p.owned))p.owned=[];if(!p.owned.includes('grade-1'))p.owned.push('grade-1');if(!Array.isArray(p.ownedBanners))p.ownedBanners=['classic'];if(!p.ownedBanners.includes('classic'))p.ownedBanners.push('classic');if(!p.banner||!banners.some(b=>b.id===p.banner)||!p.ownedBanners.includes(p.banner))p.banner='classic';if(p.avatar==='starter')p.avatar='grade-1';if(!avatarItems.some(a=>a.id===p.avatar)||(!p.owned.includes(p.avatar)&&!grades.some(g=>g.id===p.avatar&&data.xp>=g.xp)))p.avatar='grade-1';p.renameTokens=Math.max(0,Number(p.renameTokens)||0)}
function avatarById(id){return avatarItems.find(a=>a.id===id)||avatarItems[0]}
const save=()=>{try{localStorage.setItem('culture-arena-web-v1',JSON.stringify(data))}catch(e){}};
const shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};const pct=(a,b)=>b?Math.round(a/b*100):0;
function show(name){sections.forEach(n=>$(n).classList.toggle('hidden',n!==name));header();if(name==='home')home();if(name==='stats')stats();if(name==='awards')awards();if(name==='profile')profilePage();if(name==='shop')shopPage();window.scrollTo(0,0)}
function header(){const g=currentGrade(),next=nextGrade(),span=next?next.xp-g.xp:1;const done=next?data.xp-g.xp:1;$('level').textContent=g.level;$('headerRank').firstChild.textContent=g.name+' · Niv. ';$('coins').textContent=number(data.coins);$('xptext').textContent=next?number(done)+' / '+number(span):'Grade maximum atteint';$('xpbar').style.width=Math.max(0,Math.min(100,done/span*100))+'%'}
function home(){const a=Object.values(data.theme),n=a.reduce((v,x)=>v+x.n,0),c=a.reduce((v,x)=>v+x.c,0);$('games').textContent=data.games;$('accuracy').textContent=n?pct(c,n)+'%':'—';$('unseen').textContent=bank.filter(q=>!data.seen.includes(q.id)).length;$('bankNotice').textContent=`${bank.length} questions dans la banque. Les questions inédites sont prioritaires. La sauvegarde reste sur cet appareil et ce navigateur.`}
for(const t of ['Tous',...themes]){const o=document.createElement('option');o.value=t;o.textContent=t==='Tous'?'Tous les thèmes':t;$('theme').append(o)}
function setup(){show('setup');$('modeTitle').textContent=mode;$('countBox').classList.toggle('hidden',mode!=='Classique');$('modeInfo').textContent=mode==='Classique'?'Réponds à toutes les questions et accumule les points.':mode==='Survie'?'Questions sans limite : 3 vies, vise la plus longue série de bonnes réponses !':'60 secondes, −3 secondes par erreur, réponses en rafale.'}
const weights={'Histoire':1.45,'Jeux vidéo':1.35,'Sport':1.35,'Mythologie':1.35,'Littérature':0.7,'Économie':0.7};
function pool(){const p=bank.filter(q=>selectedTheme==='Tous'||q.theme===selectedTheme);const groups={};for(const q of p)(groups[q.theme]??=[]).push(q);for(const t in groups)groups[t]=[...shuffle(groups[t].filter(q=>!data.seen.includes(q.id))),...shuffle(groups[t].filter(q=>data.seen.includes(q.id)))];const result=[],counts={};let previous='';while(Object.values(groups).some(a=>a.length)){let names=Object.keys(groups).filter(t=>groups[t].length);if(names.length>1)names=names.filter(t=>t!==previous);let min=Math.min(...names.map(t=>(counts[t]||0)/(weights[t]||1)));let eligible=names.filter(t=>(counts[t]||0)/(weights[t]||1)<=min+0.65);const t=shuffle(eligible)[0];result.push(groups[t].shift());counts[t]=(counts[t]||0)+1;previous=t;}return result;}
function start(){selectedTheme=$('theme').value;selectedCount=Number($('count').value);const p=pool();if(!p.length)return;session={questions:mode==='Classique'?p.slice(0,selectedCount):p,idx:0,score:0,right:0,answered:0,streak:0,bestStreak:0,lives:3,choice:null,review:[],active:true,deadline:0,time:60};show('play');$('playingMode').textContent=mode;$('penalty').textContent='';$('survivalRecords').classList.toggle('hidden',mode!=='Survie');if(mode==='Survie')updateSurvivalRecords();if(mode==='Contre-la-montre'){session.deadline=performance.now()+60000;frame=requestAnimationFrame(tick)}render()}
function updateSurvivalRecords(){const top=[...(data.survivalTop||[])].sort((a,b)=>b-a).slice(0,3);$('survivalRecords').textContent='🏆 Tes 3 meilleures séries : '+(top.length?top.map((n,i)=>['🥇','🥈','🥉'][i]+' '+n).join('  ·  '):'aucun record pour le moment')}
function extendPool(){if(mode!=='Survie'||session.idx<session.questions.length)return;const previous=session.questions.slice(-8).map(q=>q.id);const next=pool().filter(q=>!previous.includes(q.id));session.questions.push(...(next.length?next:pool()));}
function tick(){if(!session?.active||mode!=='Contre-la-montre')return;session.time=Math.max(0,(session.deadline-performance.now())/1000);live();if(session.time<=0){finish();return}frame=requestAnimationFrame(tick)}
function live(){if(!session)return;const s=session;$('mainScore').textContent=mode==='Contre-la-montre'?s.time.toFixed(1):s.score;$('mainLabel').textContent=mode==='Contre-la-montre'?'Secondes':'Points';$('mainScore').style.color=mode==='Contre-la-montre'&&s.time<=10?'#fb7185':'#fbbf24';$('right').textContent=s.right;$('extra').textContent=mode==='Survie'?'♥'.repeat(s.lives):mode==='Contre-la-montre'?s.score:s.streak;$('extraLabel').textContent=mode==='Survie'?'Vies':mode==='Contre-la-montre'?'Points':'Série';$('progress').style.width=(mode==='Contre-la-montre'?s.time/60:mode==='Survie'?s.lives/3:(s.idx+1)/s.questions.length)*100+'%'}
function render(){const s=session;if(!s?.active)return;extendPool();const q=s.questions[s.idx];if(!q){finish();return}s.choice=null;$('position').textContent=mode!=='Classique'?'Question '+(s.answered+1):(s.idx+1)+'/'+s.questions.length;$('qtheme').textContent=q.theme;$('qlevel').textContent=q.difficulty;$('question').textContent=q.question;$('feedback').classList.add('hidden');$('next').classList.add('hidden');s.options=shuffle(q.options);const area=$('answers');area.replaceChildren();s.options.forEach((o,i)=>{const b=document.createElement('button');b.className='answer';b.textContent=String.fromCharCode(65+i)+'. '+o;b.onclick=()=>answer(i);area.append(b)});live()}
function answer(i){const s=session;if(!s?.active||s.choice!==null)return;const q=s.questions[s.idx],given=s.options[i],ok=given===q.answer;s.choice=i;s.answered++;if(ok){s.right++;s.streak++;s.bestStreak=Math.max(s.bestStreak,s.streak);s.score+=q.difficulty==='Difficile'?200:130;if(s.streak%5===0)s.score+=150}else{s.streak=0;if(mode==='Survie')s.lives--;if(mode==='Contre-la-montre'){s.deadline-=3000;$('penalty').textContent='−3 secondes !';clearTimeout(penaltyTimeout);penaltyTimeout=setTimeout(()=>$('penalty').textContent='',650)}}data.streak=Math.max(data.streak,s.streak);const t=data.theme[q.theme]||{n:0,c:0};t.n++;if(ok)t.c++;data.theme[q.theme]=t;if(!data.seen.includes(q.id))data.seen.push(q.id);s.review.push({question:q.question,answer:q.answer,given,ok,theme:q.theme});save();if(mode==='Contre-la-montre'){s.time=Math.max(0,(s.deadline-performance.now())/1000);if(s.time<=0){finish();return}s.idx++;if(s.idx>=s.questions.length){finish();return}render();return}const buttons=[...$('answers').children];buttons.forEach((b,j)=>{b.disabled=true;if(s.options[j]===q.answer)b.classList.add('good');else if(j===i)b.classList.add('bad')});$('feedback').classList.remove('hidden');$('feedback').textContent=ok?'✓ Bonne réponse !':'✕ Mauvaise réponse. Bonne réponse : '+q.answer;$('feedback').style.color=ok?'#6ee7b7':'#fda4af';$('next').classList.remove('hidden');$('next').textContent=(mode==='Classique'&&s.idx===s.questions.length-1)||(mode==='Survie'&&s.lives<=0)?'VOIR LES RÉSULTATS':'SUIVANT →';live()}
function next(){if(!session?.active)return;if((mode==='Classique'&&session.idx===session.questions.length-1)||(mode==='Survie'&&session.lives<=0)){finish();return}session.idx++;render()}
function finish(){const s=session;if(!s?.active)return;s.active=false;cancelAnimationFrame(frame);clearTimeout(penaltyTimeout);data.games++;data.xp+=s.score;data.coins+=Math.floor(s.score/100);if(mode==='Classique'&&s.answered===s.questions.length&&s.answered===s.right)data.perfect++;const old=data.records[mode]||{score:0,right:0,bestStreak:0},record=mode==='Survie'?s.bestStreak>(old.bestStreak||0):s.score>old.score;data.records[mode]={score:Math.max(old.score,s.score),right:Math.max(old.right,s.right),bestStreak:Math.max(old.bestStreak||0,s.bestStreak)};if(mode==='Survie'){data.survivalTop=[...(data.survivalTop||[]),s.bestStreak].sort((a,b)=>b-a).slice(0,3)}data.history.unshift({mode,theme:selectedTheme,score:s.score,right:s.right,total:s.answered,bestStreak:s.bestStreak});data.history=data.history.slice(0,12);syncGradeUnlocks();save();show('result');$('resultMode').textContent=mode+' · '+selectedTheme;$('finalScore').textContent=mode==='Survie'?s.bestStreak+' BONNES RÉPONSES D’AFFILÉE':s.score+' PTS';$('finalRight').textContent=s.right+'/'+s.answered;$('finalRate').textContent=pct(s.right,s.answered)+'%';$('finalXp').textContent='+'+s.score;$('record').textContent=record?'🏅 Nouveau record en '+mode+' !':'';if(mode==='Survie')$('record').textContent+=' 🏆 Top 3 : '+data.survivalTop.map((n,i)=>['🥇','🥈','🥉'][i]+' '+n).join(' · ');const area=$('review');area.replaceChildren();s.review.forEach((x,i)=>{const p=document.createElement('div');p.className='resultItem';const a=document.createElement('div');a.className='small';a.style.color=x.ok?'#6ee7b7':'#fda4af';a.textContent=(x.ok?'✓ ':'✕ ')+x.theme+' · '+(i+1);const b=document.createElement('div');b.style.cssText='font-weight:750;color:white;margin:7px 0';b.textContent=x.question;const c=document.createElement('div');c.className='muted';c.textContent='Réponse : '+x.answer;p.append(a,b,c);area.append(p)})}
function stats(){const top=(data.survivalTop||[]).sort((a,b)=>b-a).slice(0,3);$('survivalTop').textContent=top.length?top.map((n,i)=>['🥇','🥈','🥉'][i]+' '+n+' bonnes réponses consécutives').join('  ·  '):'Aucune partie Survie terminée.';const all=themes.map(t=>({t,n:data.theme[t]?.n||0,c:data.theme[t]?.c||0})),n=all.reduce((v,x)=>v+x.n,0),c=all.reduce((v,x)=>v+x.c,0);$('statsSummary').textContent=data.games+' parties · '+n+' questions · '+(n?pct(c,n)+' % de réussite':'aucune réponse');const area=$('themeStats');area.replaceChildren();const eligible=all.filter(x=>x.n>=10).sort((a,b)=>b.c/b.n-a.c/a.n);if(eligible.length){const best=document.createElement('div');best.className='panel gold';best.textContent='🏆 Meilleur thème : '+eligible[0].t+' ('+pct(eligible[0].c,eligible[0].n)+' %)';area.append(best)}all.sort((a,b)=>(b.n?b.c/b.n:-1)-(a.n?a.c/a.n:-1)).forEach(x=>{const p=document.createElement('div');p.className='panel';const row=document.createElement('div');row.className='row';const a=document.createElement('strong');a.textContent=x.t;const b=document.createElement('strong');b.className='gold';b.textContent=x.n?pct(x.c,x.n)+' %':'—';row.append(a,b);const m=document.createElement('div');m.className='muted';m.style.marginTop='8px';m.textContent=x.c+'/'+x.n+' bonnes réponses · '+(x.n>=10?'Classé':'Encore '+(10-x.n)+' pour le classement');p.append(row,m);area.append(p)});$('records').replaceChildren();['Classique','Survie','Contre-la-montre'].forEach(m=>{const x=data.records[m]||{score:0,right:0},p=document.createElement('div');p.className='row';p.style.marginBottom='9px';const a=document.createElement('span');a.textContent=m;const b=document.createElement('strong');b.className='gold';b.textContent=m==='Survie'?(x.bestStreak||0)+' de suite':x.score+' pts · '+x.right+' bonnes';p.append(a,b);$('records').append(p)});$('history').replaceChildren();if(!data.history.length)$('history').textContent='Aucune partie terminée';data.history.forEach(x=>{const p=document.createElement('div');p.className='row';p.style.marginBottom='9px';const a=document.createElement('span');a.textContent=x.mode+' · '+x.theme;const b=document.createElement('span');b.className='gold';b.textContent=x.mode==='Survie'?(x.bestStreak||0)+' de suite':x.right+'/'+x.total+' · '+x.score+' pts';p.append(a,b);$('history').append(p)})}
function awards(){const list=[['👣','Premier pas','Terminer une partie',data.games>=1],['⚡','Érudit','Obtenir 1 000 XP',data.xp>=1000],['🔥','Inarrêtable','5 bonnes réponses consécutives',data.streak>=5],['🏆','Vétéran','Terminer 10 parties',data.games>=10],['👑','Légende','Atteindre le niveau 5',currentGrade().level>=5],['🌍','Polyvalent','Jouer dans 5 thèmes',Object.values(data.theme).filter(x=>x.n>0).length>=5],['🎯','Sans faute','Terminer une manche parfaite',data.perfect>=1],['⏱️','Sprinteur','10 bonnes réponses en contre-la-montre',(data.records['Contre-la-montre']?.right||0)>=10]];const area=$('awardsList');area.replaceChildren();list.forEach(x=>{const p=document.createElement('div');p.className='panel row';p.style.opacity=x[3]?'1':'.55';const a=document.createElement('div'),b=document.createElement('strong'),c=document.createElement('div');b.textContent=x[0]+' '+x[1];c.className='muted';c.textContent=x[2];a.append(b,c);const st=document.createElement('span');st.textContent=x[3]?'✓':'🔒';p.append(a,st);area.append(p)})}

let activeProfileTab='overview';
function selectProfileTab(tab){activeProfileTab=tab;document.querySelectorAll('#profileTabs [data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===tab);b.setAttribute('aria-selected',String(b.dataset.tab===tab))});document.querySelectorAll('#profile .tab-pane').forEach(el=>el.classList.toggle('hidden',el.id!=='tab-'+tab));}
function profilePage(){ensureProfile();syncGradeUnlocks();const p=data.profile,g=currentGrade(),next=nextGrade(),a=avatarById(p.avatar),stats=Object.values(data.theme),n=stats.reduce((v,x)=>v+x.n,0),c=stats.reduce((v,x)=>v+x.c,0);$('profileAvatar').src=a.image;$('profileAvatar').alt=a.name;$('profileName').replaceWith(Object.assign(bannerNode(p.nickname,p.banner),{id:'profileName'}));$('profileRank').textContent='Grade '+g.level+'/20 · '+g.name;$('profileXP').textContent=number(data.xp)+' XP au total';$('profileGames').textContent=data.games;$('profileAccuracy').textContent=n?pct(c,n)+' %':'—';$('profileCoins').textContent=number(data.coins);$('tokenCount').textContent='Modificateurs disponibles : '+p.renameTokens;$('nextGradeText').textContent=next?'Prochain grade : '+next.name+' · encore '+number(next.xp-data.xp)+' XP':'🏆 Grade maximum atteint !';$('profileXpBar').style.width=next?((data.xp-g.xp)/(next.xp-g.xp)*100)+'%':'100%';
const summary=$('profileOverview');summary.replaceChildren();const intro=document.createElement('p');intro.textContent='Tu as débloqué '+g.level+' grade'+(g.level>1?'s':'')+' sur 20 et '+p.owned.length+' avatar(s). Continue de jouer pour progresser !';summary.append(intro);
const gl=$('gradeList');gl.replaceChildren();for(const grade of grades){const unlocked=data.xp>=grade.xp,row=document.createElement('div');row.className='grade-row '+(unlocked?'':'locked')+(grade.level===g.level?' current':'');const img=art(grade,'avatar-art small-art');const info=document.createElement('div');info.className='details';const title=document.createElement('strong');title.textContent=grade.level+'. '+grade.name;const sub=document.createElement('span');sub.textContent=number(grade.xp)+' XP total · '+(unlocked?'Avatar débloqué':'Avatar verrouillé');info.append(title,sub);const status=document.createElement('span');status.textContent=grade.level===g.level?'⭐':unlocked?'✓':'🔒';row.append(img,info,status);gl.append(row)}
const ac=$('avatarCollection');ac.replaceChildren();for(const item of avatarItems){const owned=p.owned.includes(item.id),b=document.createElement('div');b.className='cosmetic-card '+(p.avatar===item.id?'selected ':'')+(!owned?'locked':'');b.append(art(item));const name=document.createElement('strong');name.textContent=item.name;const desc=document.createElement('div');desc.className='small';desc.textContent=item.level?'Grade '+item.level:'Exclusif boutique';const action=document.createElement('button');action.textContent=!owned?'🔒 '+(item.level?'Niv. '+item.level:'Boutique'):p.avatar===item.id?'✓ Équipé':'Équiper';action.disabled=!owned||p.avatar===item.id;action.onclick=()=>{p.avatar=item.id;save();profilePage()};b.append(name,desc,action);ac.append(b)}
const bc=$('bannerCollection');bc.replaceChildren();for(const item of banners){const owned=p.ownedBanners.includes(item.id),b=document.createElement('div');b.className='cosmetic-card '+(p.banner===item.id?'selected ':'')+(!owned?'locked':'');b.append(bannerNode(p.nickname,item.id));const name=document.createElement('strong');name.textContent=item.name;const desc=document.createElement('div');desc.className='small';desc.textContent=item.price?'Boutique · '+item.price+' pièces':'Gratuite';const action=document.createElement('button');action.textContent=!owned?'🔒 Boutique':p.banner===item.id?'✓ Équipée':'Équiper';action.disabled=!owned||p.banner===item.id;action.onclick=()=>{p.banner=item.id;save();profilePage()};b.append(name,desc,action);bc.append(b)}
profileStatistics();selectProfileTab(activeProfileTab);}
function profileStatistics(){const stats=$('profileThemeStats'),rec=$('profileRecords'),hist=$('profileHistory');stats.replaceChildren();rec.replaceChildren();hist.replaceChildren();const all=themes.map(t=>({name:t,n:data.theme[t]?.n||0,c:data.theme[t]?.c||0}));const sum=document.createElement('div');sum.className='panel';sum.textContent='📊 '+data.games+' parties · '+all.reduce((n,t)=>n+t.n,0)+' questions répondues';stats.append(sum);all.sort((a,b)=>b.n-a.n).forEach(x=>{const div=document.createElement('div');div.className='panel';const row=document.createElement('div');row.className='row';const name=document.createElement('strong');name.textContent=x.name;const percent=document.createElement('strong');percent.className='gold';percent.textContent=x.n?pct(x.c,x.n)+' %':'—';row.append(name,percent);const sub=document.createElement('div');sub.className='small';sub.textContent=x.c+' / '+x.n+' bonnes réponses';div.append(row,sub);stats.append(div)});
const top=document.createElement('div');top.className='panel';const title=document.createElement('h3');title.textContent='🏆 Top 3 Survie';top.append(title);const vals=[...(data.survivalTop||[])].sort((a,b)=>b-a).slice(0,3);const body=document.createElement('p');body.textContent=vals.length?vals.map((v,i)=>['🥇','🥈','🥉'][i]+' '+v+' de suite').join(' · '):'Aucun record pour le moment';top.append(body);rec.append(top);['Classique','Survie','Contre-la-montre'].forEach(m=>{const x=data.records[m]||{},div=document.createElement('div');div.className='panel row';const name=document.createElement('strong');name.textContent=m;const score=document.createElement('span');score.className='gold';score.textContent=m==='Survie'?(x.bestStreak||0)+' de suite':(x.score||0)+' points';div.append(name,score);rec.append(div)});
if(!data.history.length){const div=document.createElement('div');div.className='panel';div.textContent='Aucune partie terminée.';hist.append(div)}else data.history.forEach(x=>{const div=document.createElement('div');div.className='panel row';const name=document.createElement('span');name.textContent=x.mode+' · '+x.theme;const val=document.createElement('strong');val.className='gold';val.textContent=x.mode==='Survie'?(x.bestStreak||0)+' de suite':x.score+' pts';div.append(name,val);hist.append(div)})}
function shopPage(){ensureProfile();syncGradeUnlocks();const p=data.profile;$('shopCoins').textContent=number(data.coins);const area=$('shopItems');area.replaceChildren();const groups=[['✏️ Objets',[{id:'rename',name:'Modificateur de pseudo',desc:'Permet de changer une fois ton pseudo.',price:100}]],['🎭 Avatars exclusifs',avatarItems.filter(a=>a.price>0).map(a=>({...a,desc:'Avatar exclusif conservé définitivement.'}))],['✨ Bannières',banners.filter(b=>b.price>0).map(b=>({...b,type:'banner',desc:'Style de pseudo débloqué définitivement.'}))]];
for(const [heading,items] of groups){const title=document.createElement('h3');title.className='shop-category';title.textContent=heading;area.append(title);for(const item of items){const owned=item.type==='banner'?p.ownedBanners.includes(item.id):item.id!=='rename'&&p.owned.includes(item.id),row=document.createElement('div');row.className='shop-card';const face=item.type==='banner'?bannerNode(p.nickname,item.id):item.id==='rename'?document.createElement('div'):art(item,'avatar-art small-art');if(item.id==='rename'){face.textContent='✏️';face.style.fontSize='30px'}const info=document.createElement('div');info.className='info';const name=document.createElement('strong');name.textContent=item.name;const desc=document.createElement('div');desc.className='small';desc.textContent=item.desc;info.append(name,desc);const buy=document.createElement('button');buy.textContent=owned?'✓ Acheté':'🪙 '+item.price;buy.disabled=owned||data.coins<item.price;buy.onclick=()=>{if(owned||data.coins<item.price)return;if(!confirm('Acheter « '+item.name+' » pour '+item.price+' pièces ?'))return;data.coins-=item.price;if(item.id==='rename')p.renameTokens++;else if(item.type==='banner')p.ownedBanners.push(item.id);else p.owned.push(item.id);save();header();shopPage();$('shopNotice').textContent='✓ Achat effectué : '+item.name};row.append(face,info,buy);area.append(row)}}}
function createProfile(){const name=validName($('newNickname').value);if(!name){$('createError').textContent='Choisis un pseudo de 3 à 18 caractères.';return}ensureProfile();data.profile.nickname=name;save();show('home')}
function changeName(){ensureProfile();const name=validName($('changeNickname').value);if(!name){$('profileNotice').textContent='Le pseudo doit contenir entre 3 et 18 caractères.';return}if(name===data.profile.nickname){$('profileNotice').textContent='Ce pseudo est déjà le tien.';return}if(data.profile.renameTokens<1){$('profileNotice').textContent='Achète d’abord un modificateur de pseudo dans la boutique.';return}data.profile.renameTokens--;data.profile.nickname=name;save();$('changeNickname').value='';profilePage();$('profileNotice').textContent='✓ Pseudo modifié !'}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;setup()});document.querySelectorAll('.back').forEach(b=>b.onclick=()=>{if(session?.active){session.active=false;cancelAnimationFrame(frame)}show('home')});$('start').onclick=start;$('quit').onclick=()=>{if(session){session.active=false;cancelAnimationFrame(frame)}show('home')};$('next').onclick=next;$('replay').onclick=start;$('goStats').onclick=()=>show('stats');$('goAwards').onclick=()=>show('awards');$('resultStats').onclick=()=>show('stats');$('goProfile').onclick=()=>show('profile');$('goShop').onclick=()=>show('shop');$('createProfileBtn').onclick=createProfile;$('newNickname').addEventListener('keydown',e=>{if(e.key==='Enter')createProfile()});$('changeNameBtn').onclick=changeName;document.querySelectorAll('#profileTabs [data-tab]').forEach(b=>b.onclick=()=>selectProfileTab(b.dataset.tab));document.querySelectorAll('[data-open-tab]').forEach(b=>b.onclick=()=>selectProfileTab(b.dataset.openTab));$('profileGoShop').onclick=()=>show('shop');if(getProfile()){syncGradeUnlocks();save()}if(!getProfile()?.nickname)show('createProfile');else show('home');
})();
